#!/usr/bin/env node
/**
 * Bundles a module's catalog/<module>/openapi.yaml (plus the paths/*.yml it $refs) into ONE file,
 * catalog/<module>/dist/openapi.yaml, with Redocly CLI — the file the API entity's `$text` points at.
 *
 *   corepack yarn openapi:bundle                     every module
 *   corepack yarn openapi:bundle creed-payment       only that module (several names allowed)
 *   corepack yarn openapi:bundle --check [modules]   exit 1 if any is missing or out of date
 *
 * Why a committed bundle instead of the catalog's `$openapi` placeholder: `$text` inserts a file
 * verbatim, so the catalog backend needs no OpenAPI module and never follows a $ref itself — what
 * Swagger UI shows is exactly the reviewed file in the repo. The price is that dist/ must be
 * regenerated and committed whenever a source changes; bitbucket-pipelines.yml does that, and
 * `--check` is what catches a hand edit or a forgotten run.
 *
 * Run `openapi:combine` first (or `openapi:build`, which runs both): it writes the entry document's
 * `paths:` list that this bundles.
 */
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, relative } from 'node:path';
import { CATALOG, REPO, cli, isMain } from './lib/modules.mjs';

const REDOCLY = join(REPO, 'node_modules', '.bin', process.platform === 'win32' ? 'redocly.cmd' : 'redocly');

const HEADER = (source) =>
  `# GENERATED by \`corepack yarn openapi:bundle\` (Redocly CLI) from ${source} — do not edit.\n` +
  '# The catalog reads this file through $text; edit the sources and re-run the script.\n';

/** @returns {{stale: number, failed: number}} */
export function bundle({ modules, check = false }) {
  const scratch = mkdtempSync(join(tmpdir(), 'openapi-bundle-'));
  let stale = 0;
  let failed = 0;

  try {
    for (const name of modules) {
      const entry = join(CATALOG, name, 'openapi.yaml');
      const target = join(CATALOG, name, 'dist', 'openapi.yaml');
      const out = join(scratch, `${name}.yaml`);

      const run = spawnSync(REDOCLY, ['bundle', entry, '--output', out], { encoding: 'utf8' });
      if (run.status !== 0) {
        failed++;
        console.error(`✗ ${relative(REPO, entry)}\n${run.stdout}${run.stderr}`);
        continue;
      }
      const bundled = HEADER(relative(join(CATALOG, name), entry)) + readFileSync(out, 'utf8');
      // Only same-document refs may be left; an external one would reach Swagger UI unresolved.
      const external = bundled.match(/\$ref:\s*['"]?[^'"#\s][^\n]*/g);
      if (external) {
        failed++;
        console.error(`✗ ${relative(REPO, entry)}: external $ref left after bundling:\n  ${external.join('\n  ')}`);
        continue;
      }

      const current = existsSync(target) ? readFileSync(target, 'utf8') : null;
      if (current === bundled) {
        console.log(`✓ ${relative(REPO, target)} up to date`);
      } else if (check) {
        stale++;
        console.error(`✗ ${relative(REPO, target)} is ${current == null ? 'missing' : 'out of date'}`);
      } else {
        mkdirSync(dirname(target), { recursive: true });
        writeFileSync(target, bundled);
        console.log(`✎ ${relative(REPO, target)} written`);
      }
    }
  } finally {
    rmSync(scratch, { recursive: true, force: true });
  }
  return { stale, failed };
}

if (isMain(import.meta.url)) await cli(bundle);
